sys_script_include.script:
var MSS_Operation_Request_Utils = Class.create();

MSS_Operation_Request_Utils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getSSIUserGroups: function() {
        var grm = new GlideRecord('sys_user_grmember');
        grm.addQuery('user', gs.getUserID());
        grm.query();

        var userGroup = '';
        if (gs.getUser().isMemberOf('iQube-SSI-User')) {

            while (grm.next()) {
                var adGroup = grm.getDisplayValue('group');
                var adGroupSysID = grm.getValue('group');
                if (adGroup.includes('-SSI-HBAP-')) {
                    userGroup = adGroupSysID;
                    break;
                }

            }
        }


        return userGroup;
    },


    getPRMUserGroups: function() {
        var grm = new GlideRecord('sys_user_grmember');
        grm.addQuery('user', gs.getUserID());
        grm.query();

        var userGroup = '';
        if (gs.getUser().isMemberOf('iQube-PRM-User')) {

            while (grm.next()) {
                var adGroup = grm.getDisplayValue('group');
                var adGroupSysID = grm.getValue('group');
                if (adGroup.includes('-PRM-')) {
                    userGroup = adGroupSysID;
                    break;
                }

            }
        }


        return userGroup;
    },

    getPRMProductUserGroupsFixFilter: function() {
        var pts_fix = this.getPRMProductUserGroupsCommon(1);
        return pts_fix;
    },

    getPRMProductUserGroups: function() {
        var productTeams = this.getPRMProductUserGroupsCommon(2);
        return productTeams;
    },

    //Get the PRM User's product AD group
    //queryType 1 fix filter
    //queryType 2 form choice
    getPRMProductUserGroupsCommon: function(queryType) {
        var productArray = [
            "ForexAndMoneyMarkets",
            "Metals",
            "FXDerivatives",
            "EnergyDerivatives",
            "FixedIncome",
            "FIAssetServicing",
            "RatesDerivatives",
            "CreditDerivatives",
            "GMOOnshoreTeam",
            "EquityDerivatives",
            "CashEquities",
            "EquityFinance",
            "EQAssetServicing",
            "Collateral",
            "ClearingAndFutures",
            "CrossProductServices",
            "BillsDepartment",
            "IDDTeam",
            "NSCGuangzhou",
            "NSCOutward",
            "OutwardDDNSCHBT",
            "OutwardDDRemittance",
            "TMDProcessing",
            "CMBFX",
            "TradedCreditRisk",
            "ProductControl",
            "BankingMiddleOffice",
            "GlobalMarketsFrontOffice",
            "Securities",
            "Treasury",
            "StaticDataMaintenance",
			"RelationshipSupportTeam",
        ];
        //"OthersNoneOfAbove",
        //"OthersNOTForClientDataServices",

        var userGroups = [];
        var grm = this.getUserGroups(gs.getUserID());
        if (grm) {
            while (grm.next()) {
                var adGroupName = grm.getDisplayValue('group');
                var regex = /-(\w+)$/;
                var match = adGroupName.match(regex);

                if (match) {
                    var extractedValue = match[1];
                    if (productArray.includes(extractedValue)) {
                        userGroups.push(extractedValue);
                    }
                }

            }
        }

        if (queryType === 2) {
            var productteamChoices = this.getTeamFieldChoices(userGroups);
            var result = JSON.stringify(productteamChoices);
            return result;
        }

        if (queryType === 1) {

            var pts = this.getTeamFieldChoicesArray(userGroups);
            return pts;
        }



    },

    //Get x_hsb11_mss_oper_0_operation_request_case, product_team, label and value
    getTeamFieldChoices: function(userGroups) {
        var jsonResult = {};
        var gr = new GlideRecord('sys_choice');
        gr.addQuery('name', 'x_hsb11_mss_oper_0_operation_request_case');
        gr.addQuery('element', 'product_team');
        gr.query();

        while (gr.next()) {
            var label = gr.getValue('label');
            var value = gr.getValue('value');

            if (label && value) {
                if (userGroups.includes(value)) {
                    jsonResult[value] = label;
                }

            }
        }

        return jsonResult;
    },

    getTeamFieldChoicesArray: function(userGroups) {
        var pts = [];
        var gr = new GlideRecord('sys_choice');
        gr.addQuery('name', 'x_hsb11_mss_oper_0_operation_request_case');
        gr.addQuery('element', 'product_team');
        gr.query();

        while (gr.next()) {
            var value = gr.getValue('value');

            if (value) {
                if (userGroups.includes(value)) {
                    pts.push(gr.getValue('value'));
                }
            }
        }
        return pts;
    },

    getUserGroups: function(userId) {
        var grm = new GlideRecord('sys_user_grmember');
        grm.addQuery('user', userId);
        grm.query();

        return grm;

    },

    // Main function to handle PRM 
    handlePRMprocess: function(case_state, case_sysId, process_type, reqrTerr, rqerTeam, recTerr, recTeam) {
        var nextState = -1;
        if (case_state == 1) {
            //submit
            nextState = this.handlePRMSubmit();
        } else {
            nextState = this.handlePRMProcessSteps(case_sysId, case_state, process_type, reqrTerr, rqerTeam, recTerr, recTeam);
        }

        return nextState;
    },

    //new submit PRM request.
    handlePRMSubmit: function() {
        var allowedGroups = [
            'PRM-ApprvrAsigner-Reqr',
            'PRM-ApprvrBsigner-Reqr',
            'PRM-ReqrNAUTH-Reqr'
        ];

        var canSubmit = -1;
        var grm = this.getUserGroups(gs.getUserID());

        if (grm) {
            while (grm.next()) {
                var adGroupName = grm.getDisplayValue('group');
                var regex = /(PRM-[a-zA-Z]+-[a-zA-Z]+)/;
                var match = adGroupName.match(regex);

                if (match) {
                    var extractedGroup = match[1];
                    if (allowedGroups.includes(extractedGroup)) {
                        canSubmit = 0;
                        break;
                    }
                }
            }
        }

        return canSubmit;
    },

    //handler PRM requesting side 1st level approve
    /*
     *process_type=1, approve
     *process_type=2, reject
     *process_type=3, cancel
     */
    handlePRMProcessSteps: function(case_sysId, case_state, process_type, reqrTerr, rqerTeam, recTerr, recTeam) {
        var nextState = -1;
        var reviewType = -1;
        var hasReviewed = this.checkApprovalList(case_sysId, gs.getUserID());
        gs.info("AAA:" + hasReviewed);
        if (hasReviewed) {
            nextState = 1; // current user already review.
            return nextState;
        }
        var lastSysId = this.getLatestReviewUser(case_sysId);
        if (!lastSysId) {
            return nextState;
        }

        //Check Territory and Team
        /* 100 pass
         * 101 Territory and Team both not match
         * 102 Territory is not match
         * 103 Team is not match
         */
        if (case_state == 6 || case_state == 7) {
            var chk_Reqr = this.checkTerritoryTeam(gs.getUserID(), reqrTerr, rqerTeam);

            if (chk_Reqr != 100) {
                return chk_Reqr;
            }
        }

        if (case_state == 8 || case_state == 9) {
            var chk_Rec = this.checkTerritoryTeam(gs.getUserID(), recTerr, recTeam);

            if (chk_Rec != 100) {
                return chk_Rec;
            }
        }

        //Reject
        if (process_type == 2) {
            nextState = 4;
            return nextState;
        }

        //Cancel
        if (process_type == 3) {
            nextState = 3;
            return nextState;
        }

        reviewType = this.checkSpecificUserGroup(case_state, lastSysId, 1);
        var currentUserReviewType = this.checkSpecificUserGroup(case_state, gs.getUserID(), 2);
        /*
         *Map 2 ->5 -> 7
         *Map 2 ->6 -> 8
         *Map 3 ->6 -> 8
         *Map 4 ->5 -> 8
         *Map 4 ->6 -> 8
         */
        //Pending 1st Level Approve
        gs.info("AAA reviewType:" + reviewType + ".currentUserReviewType:" + currentUserReviewType);
        if (case_state == 6) {
            if (reviewType == 2 && currentUserReviewType == 5) {
                nextState = 7;
                return nextState;
            }
            if (reviewType == 2 && currentUserReviewType == 6) {
                nextState = 8;
                return nextState;
            }
            if (reviewType == 3 && currentUserReviewType == 6) {
                nextState = 8;
                return nextState;
            }
            if (reviewType == 4 && currentUserReviewType == 5) {
                nextState = 8;
                return nextState;
            }
            if (reviewType == 4 && currentUserReviewType == 6) {
                nextState = 8;
                return nextState;
            } else {
                nextState = -2;
                return nextState;
            }
        } //Pending 2nd Level Approve
        else if (case_state == 7) {
            if (currentUserReviewType == 7) {
                nextState = 8;
                return nextState;
            } else {
                nextState = -2;
                return nextState;
            }
        } //Pending Receiving Process
        else if (case_state == 8) {
            if (currentUserReviewType == 8) {
                nextState = 2;
                return nextState;
            } else if (currentUserReviewType == 9) {
                nextState = 9;
                return nextState;
            } else {
                nextState = -2;
                return nextState;
            }
        } //Pending Receiving Approved
        else if (case_state == 9) {
            if (currentUserReviewType == 8 || currentUserReviewType == 10) {
                nextState = 2;
                return nextState;
            } else {
                nextState = -2;
                return nextState;
            }
        } else {
            nextState = -2;
        }

        return nextState; //-1
    },



    // Add the hanlder into the hanlder list
    addApprovedList: function(case_sysId, userId, state, order) {
        var approverGr = new GlideRecord('sysapproval_approver');
        approverGr.initialize();
        approverGr.sysapproval = case_sysId;
        approverGr.approver = userId;
        approverGr.source_table = 'x_hsb11_mss_oper_0_operation_request_case';
        approverGr.state = state;
        approverGr.order = order;
        var new_Id = approverGr.insert();

        if (!new_Id) {
            gs.error("MSS_Operation_Request_Utils - addApprovedList Fail: case_sysId:" + case_sysId + ",userId:" + userId + ",state:" + state);
        }
    },

    //Check the current user reviewed before
    checkApprovalList: function(case_sysId, userId) {
        var check = new GlideRecord('sysapproval_approver');
        check.addQuery('sysapproval', case_sysId);
        check.addQuery('approver', userId);
        check.query();
        if (check.next()) {
            return true;
        }
        return false;

    },

    getLatestReviewUser: function(case_sysId) {
        var lastSysId;
        var grApprover = new GlideRecord('sysapproval_approver');

        grApprover.addQuery('sysapproval', case_sysId);
        grApprover.orderByDesc('sys_created_on');
        grApprover.query();

        if (grApprover.next()) {
            lastSysId = grApprover.approver;
        }

        return lastSysId;
    },


    /*
     * userType = 1 latest, 2 current
     */
    checkSpecificUserGroup: function(case_state, userId, userType) {
        var reviewType = -1;

        //Requestor
        var reqrNAUTHReqr = 'PRM-ReqrNAUTH-Reqr'; //2
        var apprvrBsignerReqr = 'PRM-ApprvrBsigner-Reqr'; //3
        var apprvrAsignerReqr = 'PRM-ApprvrAsigner-Reqr'; //4

        //1st Approver
        var apprvrBsignerL1Apprvr = 'PRM-ApprvrBsigner-L1Apprvr'; //5
        var apprvrAsignerL1Apprvr = 'PRM-ApprvrAsigner-L1Apprvr'; //6

        //2nd Approver
        var apprvrAsignerL2Apprvr = 'PRM-ApprvrAsigner-L2Apprvr'; //7

        //Rec Approver
        var recSglApprvr = 'PRM-SglApprvr'; //8
        var recReqrProc = 'PRM-ReqrProc'; //9
        var recApprvr = 'PRM-Apprvr'; //10

        var grm = this.getUserGroups(userId);
        if (grm) {
            while (grm.next()) {

                var adGroupName = grm.getDisplayValue('group');

                //Rquesting side
                if (userType == 1) {
                    if (case_state == 6) {
                        if (adGroupName.includes(reqrNAUTHReqr)) {
                            reviewType = 2;
                            break;
                        } else if (adGroupName.includes(apprvrBsignerReqr)) {
                            reviewType = 3;
                            break;
                        } else if (adGroupName.includes(apprvrAsignerReqr)) {
                            reviewType = 4;
                            break;
                        }
                    } else if (case_state == 7) {
                        if (adGroupName.includes(apprvrBsignerL1Apprvr)) {
                            reviewType = 5;
                            break;
                        } else if (adGroupName.includes(apprvrAsignerL1Apprvr)) {
                            reviewType = 6;
                            break;
                        }
                    }
                } else if (userType == 2) {
                    if (case_state == 6) {
                        if (adGroupName.includes(apprvrBsignerL1Apprvr)) {
                            reviewType = 5;
                            break;
                        } else if (adGroupName.includes(apprvrAsignerL1Apprvr)) {
                            reviewType = 6;
                            break;
                        }
                    } else if (case_state == 7) {
                        if (adGroupName.includes(apprvrAsignerL2Apprvr)) {
                            reviewType = 7;
                            break;
                        }
                    }
                }

                //Recving Side
                if (case_state == 8) {
                    if (adGroupName.includes(recSglApprvr)) {
                        reviewType = 8;
                        break;
                    } else if (adGroupName.includes(recReqrProc)) {
                        reviewType = 9;
                        break;
                    }
                } else if (case_state == 9) {
                    if (adGroupName.includes(recSglApprvr)) {
                        reviewType = 8;
                        break;
                    } else if (adGroupName.includes(recApprvr)) {
                        reviewType = 10;
                        break;
                    }
                }



            }



        }

        return reviewType;
    },

    checkTerritoryTeam: function(userId, territory, team) {
        var regex_team = /-(\w+)$/;
        var regex_territory = /PRM-HB[A-Z]{2}-([A-Z]{2})$/;

        let is_territory = false;
        let is_team = false;
        let rlt = 100;

        var grm = this.getUserGroups(userId);
        if (grm) {
            while (grm.next()) {
                let adGroupName = grm.getDisplayValue('group');
                let match_territory = adGroupName.match(regex_territory);
                let match_team = adGroupName.match(regex_team);


                if (match_territory && (!is_territory)) {
                    let isoCode = match_territory[1];
                    let terr_Id = this.getCountryByISOShort(isoCode);
                    if (terr_Id) {
                        if (territory == terr_Id) {
                            is_territory = true;
                        }
                    }

                }

                if (match_team && (!is_team)) {
                    let t = match_team[1];
                    if (t.toLowerCase() == team.toLowerCase()) {
                        is_team = true;
                    }

                }

                if (is_territory && is_team) {
                    break;
                }

            }
        }


        if (!is_territory && !is_team) {
            rlt = 101;
        } else if (!is_territory) {
            rlt = 102;
        } else if (!is_team) {
            rlt = 103;
        }
        return rlt;
    },


    getCountryByISOShort: function(isoShort) {
        var sysID;
        var gr = new GlideRecord('core_country');
        gr.addQuery('iso3166_2', isoShort);
        gr.query();
        if (gr.next()) {
            sysID = gr.getValue('sys_id');
        }
        return sysID;
    },


    //Get PRM user location AD groups
    getPRMUserLocation: function() {
        var grm = this.getUserGroups(gs.getUserID());
        var groups = [];
        var country_ids = [];
        if (grm) {
            var regex = /PRM-HB[A-Z]{2}-([A-Z]{2})$/;
            while (grm.next()) {
                var groupName = grm.getDisplayValue('group'); // Get the group name
                var match = groupName.match(regex);
                if (match) {
                    var isoCode = match[1];
                    if (isoCode) { // Ensure isoCode is not an empty string
                        groups.push(isoCode);
                    }
                }
            }
        }
        var grCountry = new GlideRecord('core_country');
        grCountry.addQuery('iso3166_2', 'IN', groups);
        grCountry.query();

        if (grCountry) {
            if (grCountry) {
                while (grCountry.next()) {
                    country_ids.push(grCountry.getValue('sys_id'));
                }
            }
        }
        return country_ids;
    },

    /*
     * Get SSI approver / Signatory
     *
     */
    getSSIApprover: function() {
        var userGroups = [];
        var grm = this.getUserGroups(gs.getUserID());
        while (grm.next()) {
            // Get Location
            var regex = /-SSI-HBAP-[A-Z]{2}(?![A-Z])/;
            if (regex.test(grm.group.name)) {
                userGroups.push(grm.group.toString()); // Collect group sys_ids
            }
        }

        //Get approver group sysID
        var gr_sys_user_group = new GlideRecord('sys_user_group');
        gr_sys_user_group.addQuery('name', 'CONTAINS', '-SSI-Checker');
        gr_sys_user_group.query();
        if (gr_sys_user_group.next()) {
            userGroups.push(gr_sys_user_group.sys_id.toString());
        }

        // Get user who have the groups
        var ga = new GlideAggregate('sys_user_grmember');
        ga.addQuery('group', 'IN', userGroups);
        ga.groupBy('user');
        ga.addHaving('COUNT', '>=', userGroups.length);
        ga.query();

        // Builder user array
        var userIds = [];
        while (ga.next()) {
            var userId = ga.user.toString();
            if (gs.getUserID() == userId) {
                continue;
            }
            userIds.push(userId); // Collect user sys_ids
        }

        return userIds;

    },


    getSSINotifiers: function() {
        var userGroups = [];
        var grm = this.getUserGroups(gs.getUserID());
        while (grm.next()) {
            // Get Location
            var regex = /-SSI-HBAP-[A-Z]{2}(?![A-Z])/;
            if (regex.test(grm.group.name)) {
                userGroups.push(grm.group.toString()); // Collect group sys_ids
            }
        }

        var ga = new GlideAggregate('sys_user_grmember');
        ga.addQuery('group', 'IN', userGroups);
        ga.query();

        // Builder user array
        var userIds = [];
        while (ga.next()) {
            var userId = ga.user.toString();
            if (gs.getUserID() == userId) {
                continue;
            }
            userIds.push(userId); // Collect user sys_ids
        }

        return userIds;
    },

    isInputRole: function(role) {
		var isRole = false;
		var grm = this.getUserGroups(gs.getUserID());

        if (grm) {
            while (grm.next()) {
                var adGroupName = grm.getDisplayValue('group');
				if (adGroupName.includes(role)){
					isRole = true;
					break;
				}


            }
        }

        return isRole;
    },

    type: 'MSS_Operation_Request_Utils'
});
